```python
from typing import List

def f(N: int, A: List[int], B: List[int]) -> int:
    # Create a hash map to store the occurrences of each number in B
    b_count = {}
    for num in B:
        if num in b_count:
            b_count[num] += 1
        else:
            b_count[num] = 1

    # Initialize the count of pairs that have been seen before
    count = 0

    # Iterate over the list A and check if the corresponding number in B has been seen before
    for a, b in zip(A, B):
        if b in b_count and b_count[b] > 0:
            count += 1
            b_count[b] -= 1

    return count
```

